#include <cuda_runtime.h>
#include <chrono>
#include "study_support.h"
#include "../kmeans-cuda/cluster.cu"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}while(0)
struct GC{Case c;float *rf,*rs,*rc;int*rm;};
void reset(GC&g){auto&c=g.c;std::vector<float>f(c.n*c.f+128,-777),s(f.size(),-777),cent(c.hi*c.f+128,-777);std::copy(c.x.begin(),c.x.end(),f.begin()+64);std::vector<int>m(c.n+128,-777);CK(cudaMemcpy(g.rf,f.data(),f.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(g.rs,s.data(),s.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(g.rc,cent.data(),cent.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(g.rm,m.data(),m.size()*4,cudaMemcpyHostToDevice));}
int main(){try{std::vector<GC>cs;for(auto&c:cases()){GC g;g.c=c;CK(cudaMalloc(&g.rf,(c.n*c.f+128)*4));CK(cudaMalloc(&g.rs,(c.n*c.f+128)*4));CK(cudaMalloc(&g.rc,(c.hi*c.f+128)*4));CK(cudaMalloc(&g.rm,(c.n+128)*4));reset(g);feature_transpose<<<(c.n+256)/256,256>>>(g.rs+64,g.rf+64,c.f,c.n);CK(cudaMemcpy(g.rc+64,c.x.data(),c.lo*c.f*4,cudaMemcpyHostToDevice));find_membership<<<(c.n+256)/256,256>>>(g.rs+64,g.rc+64,g.rm+64,c.lo,c.f,c.n);CK(cudaDeviceSynchronize());cs.push_back(g);}for(int trial=1;trial<=5;trial++){std::vector<double>out;auto put=[&](double x){out.push_back(x);};auto arr=[&](const auto&v){for(auto x:v)put(x);};put(3);for(auto&g:cs){reset(g);auto&c=g.c;for(int h:{c.n,c.f,c.lo,c.hi,c.restarts})put(h);std::vector<float>actual(c.x.size());CK(cudaMemcpy(actual.data(),g.rf+64,actual.size()*4,cudaMemcpyDeviceToHost));arr(actual);}double seconds=0;int calls=0;for(auto&g:cs){auto&c=g.c;int bestk=0,bestloop=0;float bestrm=std::numeric_limits<float>::max();for(int k=c.lo;k<=c.hi;k++){put(k);CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();feature_transpose<<<(c.n+256)/256,256>>>(g.rs+64,g.rf+64,c.f,c.n);CK(cudaGetLastError());CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();calls++;std::vector<float>sw(c.x.size());CK(cudaMemcpy(sw.data(),g.rs+64,sw.size()*4,cudaMemcpyDeviceToHost));arr(sw);std::vector<int>initial(c.n);for(int i=0;i<c.n;i++)initial[i]=i;int left=c.n;for(int restart=0;restart<c.restarts;restart++){put(restart);std::vector<float>cent(k*c.f);for(int j=0;j<k;j++){if(left<=0)throw std::runtime_error("initialunderflow");for(int a=0;a<c.f;a++)cent[j*c.f+a]=c.x[initial[j]*c.f+a];std::swap(initial[j],initial[left-1]);left--;}std::vector<int>prev(c.n,-1),mem(c.n);int loop=0,iter=0,delta;do{put(iter);start=std::chrono::steady_clock::now();CK(cudaMemcpy(g.rc+64,cent.data(),cent.size()*4,cudaMemcpyHostToDevice));find_membership<<<(c.n+256)/256,256>>>(g.rs+64,g.rc+64,g.rm+64,k,c.f,c.n);CK(cudaGetLastError());CK(cudaMemcpy(mem.data(),g.rm+64,c.n*4,cudaMemcpyDeviceToHost));update(c,cent,mem,prev,delta);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();calls++;std::vector<float>devicecent(k*c.f);CK(cudaMemcpy(devicecent.data(),g.rc+64,devicecent.size()*4,cudaMemcpyDeviceToHost));arr(devicecent);arr(mem);put(delta);arr(cent);iter++;}while(delta>.001f&&(loop++<500));put(iter);start=std::chrono::steady_clock::now();float rms=rmse(c,cent);int truncated=rms;if(truncated<bestrm){bestrm=truncated;bestk=k;bestloop=restart;}seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();put(rms);put(truncated);arr(cent);}}put(bestk);put(bestloop);put(bestrm);for(auto pair:std::vector<std::pair<float*,int>>{{g.rf,c.n*c.f},{g.rs,c.n*c.f},{g.rc,c.hi*c.f}}){std::vector<float>raw(pair.second+128);CK(cudaMemcpy(raw.data(),pair.first,raw.size()*4,cudaMemcpyDeviceToHost));for(int j=0;j<64;j++)put(raw[j]);for(int j=pair.second+64;j<pair.second+128;j++)put(raw[j]);if(pair.first==g.rf&&memcmp(raw.data()+64,c.x.data(),c.x.size()*4))throw std::runtime_error("readonly");}std::vector<int>raw(c.n+128);CK(cudaMemcpy(raw.data(),g.rm,raw.size()*4,cudaMemcpyDeviceToHost));for(int j=0;j<64;j++)put(raw[j]);for(int j=c.n+64;j<c.n+128;j++)put(raw[j]);}std::string path="trial"+std::to_string(trial)+".bin";std::ofstream o(path,std::ios::binary);o.write((char*)out.data(),out.size()*8);o.close();double met[3];if(study_check(path.c_str(),met))return 1;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"independent_centroid_max_abs\":%.17g,\"timing_region\":\"sum_preallocated_transpose_iteration_upload_kernel_download_hostupdate_RMSE\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,out.size(),met[0],met[1],met[2],calls,path.c_str(),out.size());}for(auto&g:cs){cudaFree(g.rf);cudaFree(g.rs);cudaFree(g.rc);cudaFree(g.rm);}return 0;}catch(std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
